//! Cancellable pointer tracking for tab tear-off gestures.
//!
//! Unlike `drag_window`, this keeps the event loop running and does not inject
//! mouse releases or enter a system move loop. Keep the original source alive
//! while handing capture to visible attachment targets. Call `end` on the
//! current capture owner when the gesture completes.
use crate::dpi::PhysicalPosition;
use crate::window::Window;

/// Pointer and capture status sampled on the GUI event loop.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Pointer {
    /// Desktop coordinates. Physical pixels on Windows/X11; Cocoa desktop points
    /// on macOS (use `client_position`/`move_window` for DPI-safe conversion).
    pub position: PhysicalPosition<f64>,
    /// Whether the physical primary button is still down.
    pub pressed: bool,
    /// Whether native capture or tracking for the sampled window was interrupted.
    pub capture_lost: bool,
}

/// Input generated by a compositor-owned data-device drag.
#[derive(Debug, Clone, PartialEq)]
pub enum Event {
    /// Pointer entered or moved over this surface (physical client pixels).
    Motion { session: u64, position: PhysicalPosition<f64> },
    /// The pointer left every compatible surface.
    Left { session: u64 },
    /// The underlying drag was dropped.
    Released { session: u64 },
    /// Escape or compositor cancellation.
    Cancelled { session: u64 },
}

/// Queries compositor drag support without consuming the original press serial.
pub fn surface_capability(window: &Window) -> Option<bool> {
    #[cfg(wayland_platform)]
    if let crate::platform_impl::Window::Wayland(window) = &window.window {
        return window.tab_drag_capability();
    }
    let _ = window;
    None
}

/// Starts a surface drag on the existing Wayland connection. The return value
/// indicates whether the compositor supports dragging a detached toplevel.
pub fn begin_surface(window: &Window, session: u64) -> Option<bool> {
    #[cfg(wayland_platform)]
    if let crate::platform_impl::Window::Wayland(window) = &window.window {
        return window.tab_drag_begin(session);
    }
    let _ = (window, session);
    None
}

/// Attaches a not-yet-mapped toplevel to a compositor drag.
pub fn follow_surface(
    window: &Window,
    session: u64,
    offset: crate::dpi::LogicalPosition<f64>,
) -> bool {
    #[cfg(wayland_platform)]
    if let crate::platform_impl::Window::Wayland(window) = &window.window {
        return window.tab_drag_follow(session, offset);
    }
    let _ = (window, session, offset);
    false
}

/// Cancels a compositor drag, retaining the source until its terminal event.
pub fn cancel_surface(window: &Window, session: u64) {
    #[cfg(wayland_platform)]
    if let crate::platform_impl::Window::Wayland(window) = &window.window {
        window.tab_drag_cancel(session);
    }
    let _ = (window, session);
}

/// Begins an unconfined gesture; `false` means desktop tracking is unavailable.
pub fn begin(window: &Window) -> bool {
    #[cfg(windows_platform)]
    {
        use windows_sys::Win32::UI::Input::KeyboardAndMouse::{
            GetAsyncKeyState, SetCapture, VK_LBUTTON,
        };
        let hwnd = window.window.hwnd();
        if unsafe { GetAsyncKeyState(VK_LBUTTON as i32) } >= 0 {
            return false;
        }
        unsafe { SetCapture(hwnd) };
        return true;
    }
    #[cfg(x11_platform)]
    if let crate::platform_impl::Window::X(window) = &window.window {
        return window.tab_drag_begin();
    }
    #[cfg(macos_platform)]
    return window
        .window
        .maybe_wait_on_main(|_| objc2_app_kit::NSEvent::pressedMouseButtons() & 1 != 0);
    #[allow(unreachable_code)]
    {
        let _ = window;
        false
    }
}

/// Releases only capture belonging to the given capture owner.
pub fn end(window: &Window) {
    #[cfg(windows_platform)]
    {
        use windows_sys::Win32::UI::Input::KeyboardAndMouse::{GetCapture, ReleaseCapture};
        if unsafe { GetCapture() } == window.window.hwnd() {
            unsafe { ReleaseCapture() };
        }
    }
    #[cfg(x11_platform)]
    if let crate::platform_impl::Window::X(window) = &window.window {
        window.tab_drag_end();
    }
    let _ = window;
}

/// Samples the real primary button, so opening a window after release cannot
/// accidentally begin another gesture. `None` denotes a surface-local backend.
pub fn pointer(window: &Window) -> Option<Pointer> {
    #[cfg(windows_platform)]
    {
        use windows_sys::Win32::Foundation::POINT;
        use windows_sys::Win32::UI::Input::KeyboardAndMouse::{
            GetAsyncKeyState, GetCapture, VK_LBUTTON,
        };
        use windows_sys::Win32::UI::WindowsAndMessaging::GetCursorPos;
        let mut position = POINT { x: 0, y: 0 };
        if unsafe { GetCursorPos(&mut position) } == 0 {
            return None;
        }
        return Some(Pointer {
            position: PhysicalPosition::new(position.x as f64, position.y as f64),
            pressed: unsafe { GetAsyncKeyState(VK_LBUTTON as i32) } < 0,
            capture_lost: unsafe { GetCapture() } != window.window.hwnd(),
        });
    }
    #[cfg(x11_platform)]
    if let crate::platform_impl::Window::X(window) = &window.window {
        return window.tab_drag_pointer();
    }
    #[cfg(macos_platform)]
    return window.window.maybe_wait_on_main(|delegate| Some(delegate.tab_drag_pointer()));
    #[allow(unreachable_code)]
    {
        let _ = window;
        None
    }
}

/// Tests native stacking order. A followed window can be excluded so a strip
/// directly beneath it can receive the tabs; covering external windows block it.
pub fn is_pointer_target(window: &Window, ignore: Option<&Window>) -> bool {
    #[cfg(windows_platform)]
    {
        use windows_sys::Win32::Foundation::{POINT, RECT};
        use windows_sys::Win32::UI::WindowsAndMessaging::{
            GA_ROOT, GW_HWNDNEXT, GetAncestor, GetCursorPos, GetWindow, GetWindowRect,
            IsWindowVisible, WindowFromPoint,
        };
        let mut point = POINT { x: 0, y: 0 };
        if unsafe { GetCursorPos(&mut point) } == 0 {
            return false;
        }
        let mut target = unsafe { GetAncestor(WindowFromPoint(point), GA_ROOT) };
        if ignore.is_some_and(|ignore| ignore.window.hwnd() == target) {
            loop {
                target = unsafe { GetWindow(target, GW_HWNDNEXT) };
                if target.is_null() {
                    break;
                }
                let mut rect = RECT { left: 0, top: 0, right: 0, bottom: 0 };
                if unsafe { IsWindowVisible(target) } != 0
                    && unsafe { GetWindowRect(target, &mut rect) } != 0
                    && point.x >= rect.left
                    && point.x < rect.right
                    && point.y >= rect.top
                    && point.y < rect.bottom
                {
                    break;
                }
            }
        }
        return target == window.window.hwnd();
    }
    #[cfg(x11_platform)]
    if let crate::platform_impl::Window::X(window) = &window.window {
        let ignore = ignore.and_then(|ignore| match &ignore.window {
            crate::platform_impl::Window::X(window) => Some(window.xlib_window() as u32),
            #[allow(unreachable_patterns)]
            _ => None,
        });
        return window.tab_drag_is_pointer_target(ignore);
    }
    #[cfg(macos_platform)]
    {
        let below = ignore
            .map(|ignore| {
                ignore.window.maybe_wait_on_main(|delegate| delegate.tab_drag_window_number())
            })
            .unwrap_or(0);
        return window
            .window
            .maybe_wait_on_main(move |delegate| delegate.tab_drag_is_pointer_target(below));
    }
    #[allow(unreachable_code)]
    {
        let _ = (window, ignore);
        false
    }
}

/// Converts native desktop coordinates into physical client coordinates.
pub fn client_position(
    window: &Window,
    position: PhysicalPosition<f64>,
) -> Option<PhysicalPosition<f64>> {
    let origin = window.inner_position().ok()?;
    #[cfg(macos_platform)]
    let position = PhysicalPosition::new(
        position.x * window.scale_factor(),
        position.y * window.scale_factor(),
    );
    Some(PhysicalPosition::new(position.x - f64::from(origin.x), position.y - f64::from(origin.y)))
}

/// Moves a window using native desktop coordinates and a logical grab offset.
pub fn move_window(
    window: &Window,
    position: PhysicalPosition<f64>,
    offset: crate::dpi::LogicalPosition<f64>,
) {
    let scale = window.scale_factor();
    #[cfg(macos_platform)]
    let position = PhysicalPosition::new(position.x * scale, position.y * scale);
    let target = PhysicalPosition::new(
        (position.x - offset.x * scale) as i32,
        (position.y - offset.y * scale) as i32,
    );
    // Some event loops immediately resume application work on window movement.
    // Avoid requesting an unchanged position and recursively waking that loop.
    if window.outer_position().ok() != Some(target) {
        window.set_outer_position(target);
    }
}
